// 当前书源版本号，切勿修改，否则影响更新的识别
const localVersion = '4.10.4';

function login(flag) {
	if (flag == undefined) {
		result = JSON.parse(source.getLoginInfo())
	} else {
		java.longToast("\n\n💞正在登录中...")
		putLoginInfo(JSON.stringify(result))
	}
	let base_url = getArgument('server')
	let zdyserver = String(result['自定义服务器(可不填)']);
	if (zdyserver.includes('http')) {
		setArgument('server', zdyserver);
		if (getKey(String(cookie.getCookie(base_url)))){
			let cookies=cookie.getCookie(base_url)
			removeCookie(base_url)
			cookie.setCookie(zdyserver,cookies)
		}
		java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
	}
	let zdytone_id = String(result['听书Ai音色填写后点击右上角✔'] || '');
	if (zdytone_id) {
		setArgument('tone_id', zdytone_id);
	} else {
		setArgument('tone_id', '默认音色');
	}
	let plcolor = String(result['自定义评论颜色(可不填)'] || '#000000');
	if (plcolor) {
		setArgument('plcolor', plcolor);
	} else {
		setArgument('plcolor', '#000000');
	}
	let zdysources = String(result['自定义搜索源(多个用英文,分割)'] || '');
	if (zdysources) {
		setArgument('source', zdysources);
	};
	base_url = getArgument('server')
	let register_email = String(result['邮箱'])
	let password = String(result['密码'])
	let key = String(result['密钥']||'')

	//java.log(cookie.getCookie(base_url))
	if ((register_email && password || key)&& !String(getKey(String(cookie.getCookie(base_url))))) {
		removeCookie(base_url)
		let deviceKey = '';		
	  try {
				deviceKey = java.deviceID();
			} catch (e) {
				deviceKey = java.androidId();
		};
	let deviceId = deviceKey;
		  if (register_email && password){
			let options = JSON.stringify({
				method: 'POST',
				headers: {
					'Content-Type': 'application/json'
				},
				body: JSON.stringify({
					register_email: result['邮箱'],
					password: result['密码']
				})
			})
			try {
				let data = JSON.parse(java.ajax(`${base_url}/login_api,${options}`))
				if (data.code == 0) {
					//java.toast(deviceId)
					java.toast("\n\n✅️登录成功")
					cookie.setCookie(base_url, `qttoken=${data.key};deviceId=${deviceId}`)
					result['密钥']=data.key
					putLoginInfo(JSON.stringify(result))
				} else {
					java.toast('\n\n💔'+data.msg || "登录失败，请重试！")
				}
			} catch (e) {
				java.toast("\n\n💔登录失败，请重试！\n" + e.message)
			}
		} else {
			cookie.setCookie(base_url, `qttoken=${key};deviceId=${deviceId}`)
			let res=java.ajax(`${base_url}/user_api,{"method":"POST","headers":{"cookie":"${cookie.getCookie(base_url)}"}}`)			
			try {
				res=JSON.parse(res)
				if (res.id!=undefined) {
					java.toast('\n\n密钥登录成功')
					result['邮箱'] = res.email
					putLoginInfo(JSON.stringify(result))
				} else {
					throw new Error()
				}
			} catch(e) {
				java.log(e)
				java.toast("\n\n💔登录失败")
			}
		}
	} else if (flag&&String(getKey(String(cookie.getCookie(base_url))))) {
		java.toast("\n\n当前✅️已登录，请🚫退出登录后重新登录");
		//checkStatus();
	} else if (flag) {
		java.toast("\n\n⛔️请先填写邮箱和密码");
		}
}

// 检测服务器
function checkNet() {
	let url = getArgument('server');
	java.longToast(`\n\n♻️正在检测：${url}\n请稍等~`);
	let date1 = new Date().getTime();
	let html = java.ajax(url+'/login');
	let date2 = new Date().getTime();
	let t = date2 - date1;
 let c = String(html).indexOf('大灰狼');
  let code = 1;
 	let time = t / 1000 + 's';
	let logTime = '【' + url + '】\n┋┋\n' + '解析时间：' + time;
    if ( c == -1 || t > 5000) {
        java.longToast('\n💔【访问失败提示】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️当前接口无法访问(可能被墙)♣️\n┋┋\n请切换其他接口/切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t < 1000) {
        java.longToast('\n💖【网络环境优良】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n❤️延迟低，推荐使用此接口❤️\n┋┋\n网络环境优良，请继续保持状态\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t >= 1000 && t < 2000) {
        java.longToast('\n💛【网络环境一般】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他接口或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t >= 2000 && t < 5000) {
        java.longToast('\n💔【网络环境堪忧】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他接口或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    }
	}

	function isVips(res) {
    let isVIP = '';
    let vipEndTime = res.vip_end_time;
    let formattedDate = '';

    if (vipEndTime && vipEndTime !== 0) {
        let date = new Date(vipEndTime * 1000);
        formattedDate = `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-${date.getDate().toString().padStart(2, '0')}`;
        let currentTime = Math.floor(Date.now() / 1000);
        let remainingDays = Math.ceil((vipEndTime - currentTime) / (24 * 60 * 60));
        if (currentTime > vipEndTime) {
            isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"} (已过期)`;
        } else if (remainingDays <= 7) {
            isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"} 剩余${remainingDays}天`;
        } else {
            if (vipEndTime < 1912946812) {
                isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"}(${formattedDate})`;
            } else {
                isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"} (永久)`;
            }
        }
    } else {
        isVIP = '您尚未开通VIP';
    }
    return isVIP;
}

function checkStatus() {
	java.longToast('\n\n♻️检测中...');
	let base_url = getArgument('server')
	let res=java.ajax(`${base_url}/user_api,{"method":"POST","headers":{"cookie":"${cookie.getCookie(base_url)}"}}`)	
	try {
				res=JSON.parse(res)
				if (res.id!=undefined) {
					result['邮箱'] = res.email
					putLoginInfo(JSON.stringify(result))
					let devices
					try {
						devices = JSON.parse(res.device).length;
					} catch (e) {
						devices = res.device ? 1 : 0;
					}
					let isVip = isVips(res);
					tips= `
┏┅┅┅┅┅┅┱┄┄┄┄┄┄┄┄┄┄┐
　✉️邮箱　　　　${res.email.replace(/(.{3}).*?@/,"$1***@").padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🔑密钥　　　　${(`${res.user_key.substring(0,4)}***${res.user_key.slice(-4)}`).padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　📅注册时间　　${java.timeFormat(res.register_time*1000).padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🗒️今日阅读　　${(java.timeFormat(new Date()).slice(0,10)==java.timeFormat(res.last_read_time * 1000).slice(0,10)?res.day_read_count:0).toString().padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　📚累计阅读　　${res.all_read_count.toString().padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🕓最后阅读　　${(res.last_read_time != 0?java.timeFormat(res.last_read_time * 1000):'未阅读').padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　📱关联设备　　${devices.toString().padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　👑会员状态　　${isVip.padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🚫封禁状态　　${res.is_banned?'已封禁':'正常　'}　　　　　　　
┗┅┅┅┅┅┅┹┄┄┄┄┄┄┄┄┄┄┘
`
					java.log(tips)
					java.longToast(tips)
				} else {
					throw new Error(res.msg)
				}
			} catch(e) {
				//java.log(e)
				java.toast("\n检测登录失败\n"+e.message)
			}
}

function clearDevice() {
	let base_url = getArgument('server')
  let res=java.ajax(`${base_url}/clear,{"method":"POST","headers":{"cookie":"${cookie.getCookie(base_url)}"}}`)
	java.toast(res.code === 0 ? "\n\n📴设备清除成功" : res.msg)
	Packages.java.lang.Thread.sleep(500)
	checkStatus()
}
// 保存登录UI信息
function putLoginInfo(info) {
	try {
		let key = java.androidId()
		let encodeStr = Packages.android.util.Base64.encodeToString(java.createSymmetricCrypto("AES", key).encrypt(info), 2)
		cache.put(`userInfo_${source.getKey()}`, encodeStr)
		return true
	} catch (e) {
		java.log(e)
		return source.putLoginInfo(info)
	}
}

// 填写密钥
function loginqt() {
	java.startBrowserAwait(getArgument('server') + '/login', '登录大灰狼小说书源');
}

//登录番茄
function fq_login() {
	try {
		java.startBrowserAwait("https://fanqienovel.com/", "登录")
	} catch (e) {
		java.toast(e)
	}
	try {
		cookie.removeCookie("snssdk.com")
	} catch (e) {}
	var cookie_ = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
    let user
    try {
      user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
        method: "GET",
        headers: {
          "Cookie": cookie_
        }
      }))).data.name
     } catch (e) {java.log(e)}
    if (!cookie_ || cookie_ == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败")
        return false
    }
    java.toast("\n\n欢迎 " + user + "\n登录成功！")
    	return true
}

//退出登录
function logout() {
	cookie.removeCookie("fanqienovel.com");
	cookie.removeCookie("snssdk.com");
	cookie.removeCookie("69shuba.com");
	/*
	let servers = host
	for (let server of servers) {
		removeCookie(server);
	}
	*/
	removeCookie(getArgument('server'))
	java.toast("退出登录成功");
}

//获取参数
function getArgument(key) {
	let open_argument = source.getVariable();
	open_argument = getArguments(open_argument, '');
	return open_argument[key];
}

//设置参数
function setArgument(key, value) {
	let open_argument = source.getVariable();
	open_argument = getArguments(open_argument, '');
	open_argument[key] = value;
	open_argument = JSON.stringify(open_argument);
	source.setVariable(open_argument);
	return open_argument;
}

// 设置本地or云端访问
function get_proxy() {
	let proxy = getArgument('proxy');
